CREATE TABLE taxonomy(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind varchar(30) NOT NULL,name varchar(200) NOT NULL,parent_id bigint REFERENCES taxonomy(id),sort_order integer NOT NULL DEFAULT 0);
CREATE INDEX taxonomy_parent ON taxonomy(kind,parent_id);
CREATE TABLE files(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,original_name varchar(255) NOT NULL,storage_name varchar(64) NOT NULL UNIQUE,mime varchar(100) NOT NULL,size bigint NOT NULL,checksum varchar(64) NOT NULL,created_at bigint NOT NULL);
CREATE TABLE contents(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind varchar(30) NOT NULL,title varchar(200) NOT NULL,body text NOT NULL,metadata text NOT NULL,
 topic_id bigint REFERENCES taxonomy(id),category_id bigint REFERENCES taxonomy(id),file_id bigint REFERENCES files(id),
 source_url varchar(2000) NOT NULL DEFAULT '',license varchar(300) NOT NULL DEFAULT '',status varchar(30) NOT NULL DEFAULT 'draft',priority integer NOT NULL DEFAULT 0,pinned boolean NOT NULL DEFAULT false,
 published_at bigint,expires_at bigint,version integer NOT NULL DEFAULT 1,reviewed_by bigint REFERENCES admins(id),created_at bigint NOT NULL,updated_at bigint NOT NULL,
 search_text text NOT NULL DEFAULT ''
);
CREATE INDEX contents_listing ON contents(kind,status,pinned DESC,priority DESC,id DESC);
CREATE TABLE content_revisions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,content_id bigint NOT NULL REFERENCES contents(id) ON DELETE CASCADE,version integer NOT NULL,snapshot text NOT NULL,admin_id bigint REFERENCES admins(id),created_at bigint NOT NULL,UNIQUE(content_id,version));
CREATE TABLE university_books(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source_key varchar(64) NOT NULL UNIQUE,title text NOT NULL,details text NOT NULL,search_text text NOT NULL,category varchar(32) NOT NULL DEFAULT 'general',deleted boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1);
CREATE INDEX university_books_category ON university_books(category,deleted,id);
CREATE TABLE catalog_generations(scope varchar(32) PRIMARY KEY,revision bigint NOT NULL DEFAULT 1);
INSERT INTO catalog_generations(scope) VALUES('contents'),('books');
CREATE TABLE student_verifications(user_id bigint PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,status varchar(20) NOT NULL DEFAULT 'collecting',phase varchar(20) NOT NULL DEFAULT 'phone',details text NOT NULL,student_hash varchar(64),revision integer NOT NULL DEFAULT 1,review_note varchar(1000) NOT NULL DEFAULT '',reviewed_by bigint REFERENCES admins(id),reviewed_at bigint,created_at bigint NOT NULL,updated_at bigint NOT NULL);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='unibot_app') THEN
 GRANT SELECT,INSERT,UPDATE,DELETE ON taxonomy,files,contents,content_revisions,university_books,catalog_generations,student_verifications TO unibot_app;
 GRANT SELECT,INSERT,UPDATE ON users TO unibot_app;
 GRANT SELECT ON settings TO unibot_app;
 GRANT USAGE ON SEQUENCE users_id_seq,taxonomy_id_seq,files_id_seq,contents_id_seq,content_revisions_id_seq,university_books_id_seq TO unibot_app;
END IF;END $$;
CREATE TABLE catalog_commands(request_key varchar(64) PRIMARY KEY,actor_id bigint NOT NULL REFERENCES admins(id),request_hash varchar(64) NOT NULL,result text NOT NULL);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='unibot_app') THEN GRANT SELECT,INSERT,UPDATE ON catalog_commands TO unibot_app; END IF; END $$;
